package net.minecraft.world.level.levelgen.synth;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import it.unimi.dsi.fastutil.doubles.*;
import org.junit.jupiter.api.*;
/** Actual Normal constructor iterator, alias, reentry and live-tail boundaries. */
class NormalConstructorContractTest {
 @BeforeAll static void bootstrap(){net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();}
 @Test void rangeIteratorFailureComesAfterBothRealChildren(){var failure=new RuntimeException("actual range iterator");var values=new DoubleArrayList(new double[]{1,1}){@Override public DoubleListIterator iterator(){throw failure;}};var source=new CompositeConstructorContractTest.Source();assertSame(failure,assertThrows(RuntimeException.class,()->NormalNoise.create(source,new NormalNoise.NoiseParameters(-1,values))));assertEquals(List.of("forkPositional","forkPositional"),source.calls);assertEquals(List.of("octave_-1","octave_0","octave_-1","octave_0"),source.hashes);}
 @Test void rangeReadsIndexBeforeEachActualValue(){var trace=new ArrayList<String>();var values=new DoubleArrayList(new double[]{1,0}){@Override public DoubleListIterator iterator(){trace.add("iterator");var actual=super.iterator();return new DoubleListIterator(){public boolean hasNext(){trace.add("hasNext");return actual.hasNext();}public int nextIndex(){trace.add("index");return actual.nextIndex();}public double nextDouble(){trace.add("value");return actual.nextDouble();}public boolean hasPrevious(){throw new AssertionError("previous");}public double previousDouble(){throw new AssertionError("previous");}public int previousIndex(){throw new AssertionError("previous");}};}};NormalNoise.create(new CompositeConstructorContractTest.Source(),new NormalNoise.NoiseParameters(-1,values));assertEquals(List.of("iterator","hasNext","index","value","hasNext","index","value","hasNext"),trace);}
 @Test void rangeIteratorMayConstructAnotherNoiseOnTheSameSource(){var source=new CompositeConstructorContractTest.Source();var inner=new ArrayList<NormalNoise>();boolean[] armed={true};var values=new DoubleArrayList(new double[]{1,1}){@Override public DoubleListIterator iterator(){if(armed[0]){armed[0]=false;inner.add(NormalNoise.create(source,new NormalNoise.NoiseParameters(-1,this)));}return super.iterator();}};var parameters=new NormalNoise.NoiseParameters(-1,values);var outer=NormalNoise.create(source,parameters);assertSame(parameters,outer.parameters());assertEquals(1,inner.size());assertEquals(4,source.calls.size());assertEquals(8,source.hashes.size());assertNotSame(outer,inner.getFirst());}
 @Test void trailingAmplitudeChangeAfterAsymmetricConstructionUsesBothActualChildren(){var amplitudes=new DoubleArrayList(new double[]{1,1});var source=new CompositeConstructorContractTest.Source();source.onHash=()->amplitudes.add(1.0);var parameters=new NormalNoise.NoiseParameters(-1,amplitudes);var noise=NormalNoise.create(source,parameters);assertSame(parameters,noise.parameters());assertEquals(4599426361975877692L,Double.doubleToRawLongBits(noise.getValue(12.25,-4.5,6.75)));amplitudes.set(2,2.0);assertEquals(4599037845078277601L,Double.doubleToRawLongBits(noise.getValue(12.25,-4.5,6.75)),"actual second-child tail stayed stale");}
}
